// The Rust engine for Android: libs built by cargo-ndk and Kotlin bindings generated by
// `cargo xtask bindings` (ADR-0025, ADR-0026). Both are generated per variant, never committed.

import com.android.build.api.variant.Variant
import javax.inject.Inject

plugins {
    alias(libs.plugins.android.library)
}

val repoRoot: File = rootDir.resolve("../..").canonicalFile
val abiList: List<String> =
    providers.gradleProperty("labely.abis").get().split(",").map(String::trim).filter(String::isNotEmpty)
val cargoBin: String =
    providers.environmentVariable("CARGO").orNull
        ?: File(System.getProperty("user.home"), ".cargo/bin/cargo").takeIf(File::exists)?.path
        ?: "cargo"

android {
    namespace = "org.labely.ffi"
    compileSdk {
        version = release(37) { minorApiLevel = 2 }
    }
    ndkVersion = "30.0.16248370"

    defaultConfig {
        minSdk { version = release(26) }
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        consumerProguardFiles("consumer-rules.pro")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

/** Builds `liblabely_ffi.so` for each ABI into `outDir/<abi>/`. */
abstract class CargoNdkTask @Inject constructor(private val exec: ExecOperations) : DefaultTask() {
    @get:Input abstract val cargo: Property<String>
    @get:Input abstract val abis: ListProperty<String>
    @get:Input abstract val release: Property<Boolean>
    @get:Input abstract val minSdk: Property<Int>
    @get:Internal abstract val workspace: DirectoryProperty
    @get:Internal abstract val ndkDir: DirectoryProperty
    @get:OutputDirectory abstract val outDir: DirectoryProperty

    @TaskAction
    fun build() {
        val args = mutableListOf(cargo.get(), "ndk", "--platform", minSdk.get().toString())
        abis.get().forEach { args += listOf("-t", it) }
        args += listOf("-o", outDir.get().asFile.path, "build", "-p", "labely-ffi", "--lib")
        if (release.get()) args += "--release"
        exec.exec {
            workingDir = workspace.get().asFile
            environment("ANDROID_NDK_HOME", ndkDir.get().asFile.path)
            commandLine(args)
        }
    }
}

/** Generates the UniFFI Kotlin sources into `outDir`. */
abstract class UniffiBindingsTask @Inject constructor(private val exec: ExecOperations) : DefaultTask() {
    @get:Input abstract val cargo: Property<String>
    @get:Internal abstract val workspace: DirectoryProperty
    @get:OutputDirectory abstract val outDir: DirectoryProperty

    @TaskAction
    fun generate() {
        val out = outDir.get().asFile
        out.deleteRecursively()
        exec.exec {
            workingDir = workspace.get().asFile
            commandLine(cargo.get(), "xtask", "bindings", "kotlin", out.path)
        }
    }
}

androidComponents {
    onVariants { variant: Variant ->
        val name = variant.name.replaceFirstChar(Char::uppercase)
        val ndk = sdkComponents.ndkDirectory
        val cargoNdk =
            tasks.register<CargoNdkTask>("cargoNdk$name") {
                group = "rust"
                description = "Builds the Labely engine for ${abiList.joinToString()}."
                cargo = cargoBin
                abis = abiList
                release = variant.buildType == "release"
                minSdk = 26
                workspace = repoRoot
                ndkDir = ndk
                // cargo decides what is up to date.
                outputs.upToDateWhen { false }
            }
        val bindings =
            tasks.register<UniffiBindingsTask>("uniffiBindings$name") {
                group = "rust"
                description = "Generates the UniFFI Kotlin bindings."
                cargo = cargoBin
                workspace = repoRoot
                outputs.upToDateWhen { false }
            }
        variant.sources.jniLibs?.addGeneratedSourceDirectory(cargoNdk, CargoNdkTask::outDir)
        variant.sources.kotlin?.addGeneratedSourceDirectory(bindings, UniffiBindingsTask::outDir)
    }
}

dependencies {
    // UniFFI's Kotlin bindings call the library through JNA.
    api("${libs.jna.get()}@aar")

    androidTestImplementation(libs.androidx.test.junit)
    androidTestImplementation(libs.androidx.test.runner)
}
